package com.opensocket.aievent.core.issuetracking.relay;
import java.time.OffsetDateTime; import java.util.Objects;
public record RelayCompensation(String tenantId,String compensationId,String topologyId,String canonicalRelationId,String reasonCode,String requestedBy,RelayCompensationStatus status,int totalEdges,int compensatedEdges,int failedEdges,long version,OffsetDateTime createdAt,OffsetDateTime updatedAt,String correlationId) {
 public RelayCompensation { tenantId=req(tenantId,"tenantId");compensationId=req(compensationId,"compensationId");topologyId=req(topologyId,"topologyId");canonicalRelationId=req(canonicalRelationId,"canonicalRelationId");reasonCode=req(reasonCode,"reasonCode");requestedBy=req(requestedBy,"requestedBy");status=Objects.requireNonNull(status,"status is required");if(totalEdges<0||compensatedEdges<0||failedEdges<0)throw new IllegalArgumentException("compensation counts cannot be negative");if(version<1)throw new IllegalArgumentException("version must be positive");createdAt=Objects.requireNonNull(createdAt,"createdAt is required");updatedAt=Objects.requireNonNull(updatedAt,"updatedAt is required");correlationId=norm(correlationId); }
 private static String req(String v,String n){Objects.requireNonNull(v,n+" is required");String x=v.trim();if(x.isEmpty())throw new IllegalArgumentException(n+" is required");return x;} private static String norm(String v){return v==null?"":v.trim();}
}
